using UnityEngine;using DG.Tweening;using LWS.TruckSports;
namespace LWS.TruckTargetLaunch {
public enum TargetFlight{Approach,Airborne,Passive,Resolved}
public sealed class TargetRacer:MonoBehaviour {
 public TargetMatch match;public SportsEventTruck truck;public Transform[] wings;public ParticleSystem crash;public AudioSource wind;public int slot;public TargetFlight Phase{get;private set;}public bool Dived{get;private set;}public float FlightAge{get;private set;}public float Age{get;private set;}public Vector3 LaunchVelocity{get;private set;}public Vector3 LandingPoint{get;private set;}public int TopContacts{get;private set;}public int AirContacts{get;private set;}public readonly SportsLimitedAftertouch touch=new SportsLimitedAftertouch();
 readonly Tween[] folds=new Tween[2];readonly RaycastHit[] swept=new RaycastHit[24];Vector3 previous;Quaternion previousRotation;
 public void ResetRacer(Vector3 position){foreach(var tween in folds)tween?.Kill();Dived=false;touch.Reset(1.6f,Vector2.zero);Age=FlightAge=0;TopContacts=AirContacts=0;Phase=TargetFlight.Approach;for(int i=0;i<wings.Length;i++)wings[i].localRotation=Quaternion.Euler(0,0,i==0?-80:80);truck.Prepare(position,Quaternion.Euler(13,0,0));previous=truck.body.position;previousRotation=truck.body.rotation;crash.Stop(true,ParticleSystemStopBehavior.StopEmittingAndClear);}
 void Wings(bool open){for(int i=0;i<wings.Length;i++){folds[i]?.Kill();folds[i]=wings[i].DOLocalRotate(new Vector3(0,0,open?0:i==0?-80:80),.35f).SetEase(Ease.OutCubic);}}
 public void Tick(Vector2 drive,bool dive,float dt){Age+=dt;if(Phase==TargetFlight.Approach){truck.TickDrive(drive);if(truck.body.position.z>72&&!truck.Grounded&&truck.body.linearVelocity.z>1){Phase=TargetFlight.Airborne;FlightAge=0;LaunchVelocity=truck.body.linearVelocity;touch.Reset(1.6f,drive);truck.Power(false);Wings(true);match.Launched(slot,LaunchVelocity);}if(Age>35||truck.body.position.y< -10||Mathf.Abs(truck.body.position.x)>90)Miss();}
  else if(Phase==TargetFlight.Airborne){FlightAge+=dt;touch.Tick(truck.body,drive,dt);if(dive&&!Dived){Dived=true;Wings(false);match.Dived(slot);}float lift=Dived?-.18f:.24f;truck.body.AddForce(Vector3.up*(Physics.gravity.magnitude*lift),ForceMode.Acceleration);var horizontal=Vector3.ProjectOnPlane(truck.body.linearVelocity,Vector3.up);truck.body.AddForce((match.CurrentWind-horizontal)*.018f,ForceMode.Acceleration);}
  if(Phase==TargetFlight.Airborne||Phase==TargetFlight.Passive){if(truck.body.position.y< -18||FlightAge>18||Age>48||truck.body.position.z>260||Mathf.Abs(truck.body.position.x)>150)Miss();}
 }
 public void ObservePastStep(){if(Phase==TargetFlight.Airborne||Phase==TargetFlight.Passive)SweptLanding();previous=truck.body.position;previousRotation=truck.body.rotation;}
 void SweptLanding(){var delta=truck.body.position-previous;if(delta.y>=-.001f||delta.sqrMagnitude<.0001f)return;var shape=truck.shape;Vector3 origin=previous+previousRotation*shape.center;int n=Physics.BoxCastNonAlloc(origin,shape.size*.5f,delta.normalized,swept,previousRotation,delta.magnitude,1,QueryTriggerInteraction.Ignore);if(n==swept.Length)throw new System.InvalidOperationException("Target landing sweep buffer saturated");float best=float.MaxValue;RaycastHit selected=default;for(int i=0;i<n;i++)if(swept[i].collider==match.targetCollider&&swept[i].normal.y>.6f&&swept[i].distance<best){best=swept[i].distance;selected=swept[i];}if(best<float.MaxValue){float fraction=Mathf.Clamp01(best/delta.magnitude);var center=Vector3.Lerp(previous,truck.body.position,fraction)+Quaternion.Slerp(previousRotation,truck.body.rotation,fraction)*truck.body.centerOfMass;Lock(center,selected.normal,delta.y/Time.fixedDeltaTime,selected.point);}}
 void Lock(Vector3 center,Vector3 normal,float incomingY,Vector3 point){if(Phase==TargetFlight.Resolved||Phase==TargetFlight.Approach)return;if(!TargetRules.TopContact(normal.y,incomingY,point.y,match.target.position.y))return;TopContacts++;LandingPoint=center;truck.Power(false);Wings(false);int score=match.ScoreAt(center);Phase=TargetFlight.Resolved;match.Lock(slot,score,center);}
 void Miss(){if(Phase==TargetFlight.Resolved)return;Phase=TargetFlight.Resolved;truck.Power(false);Wings(false);LandingPoint=truck.body.position;crash.transform.position=truck.body.position;crash.Play();match.Lock(slot,0,LandingPoint);}
 void OnCollisionEnter(Collision collision){if(!match.Live||!match.RoundLive)return;var other=collision.rigidbody!=null?collision.rigidbody.GetComponent<TargetRacer>():null;if(other!=null&&(Phase==TargetFlight.Airborne||other.Phase==TargetFlight.Airborne))AirContacts++;if(collision.collider==match.targetCollider){if(Phase==TargetFlight.Airborne){Phase=TargetFlight.Passive;truck.Power(false);Wings(false);}for(int i=0;i<collision.contactCount;i++){var contact=collision.GetContact(i);Lock(truck.body.worldCenterOfMass,contact.normal,collision.relativeVelocity.y,contact.point);}match.Impact(slot,collision.relativeVelocity.magnitude);}else if(collision.collider==match.missGround&&(Phase==TargetFlight.Airborne||Phase==TargetFlight.Passive||Phase==TargetFlight.Approach))Miss();}
 void Update(){if(wind==null)return;float volume=match.Live&&Phase==TargetFlight.Airborne&&Application.isFocused?match.settings.sfx*.05f:0;wind.volume=volume;wind.pitch=.7f+truck.body.linearVelocity.magnitude*.015f;if(volume>.001f){if(!wind.isPlaying)wind.Play();}else wind.Stop();}
 public void Freeze(){foreach(var tween in folds)tween?.Pause();truck.Power(false);truck.body.isKinematic=true;if(wind!=null)wind.Stop();crash.Pause();}
 void OnDisable(){foreach(var tween in folds)tween?.Kill();if(wind!=null)wind.Stop();}
}
}
